const steps = [
  {
    number: "01",
    title: "Browse Courses",
    description: "Find the course that fits your stage.",
  },
  {
    number: "02",
    title: "Create Account",
    description: "Sign up with your university details.",
  },
  {
    number: "03",
    title: "Enroll",
    description: "Complete enrollment from your dashboard.",
  },
  {
    number: "04",
    title: "Start Learning",
    description: "Access everything at your own pace.",
  },
];

export function HowToEnroll() {
  return (
    <section className="bg-cream px-6 py-20 lg:py-24">
      <div className="mx-auto max-w-6xl">
        <header className="text-center">
          <h2 className="font-heading text-3xl font-bold text-primary lg:text-4xl">
            How to enroll
          </h2>
          <p className="mx-auto mt-4 max-w-2xl text-muted">
            A clear path from choosing a course to starting your preparation.
          </p>
        </header>

        <div className="relative mt-16">
          <div
            aria-hidden="true"
            className="absolute left-0 right-0 top-8 hidden h-px bg-border lg:block"
          />
          <ol className="relative grid gap-10 lg:grid-cols-4 lg:gap-8">
            {steps.map((step) => (
              <li key={step.number}>
                <span className="font-heading text-4xl font-extrabold text-accent">
                  {step.number}
                </span>
                <h3 className="mt-3 text-base font-semibold text-primary">
                  {step.title}
                </h3>
                <p className="mt-1 max-w-xs text-sm leading-6 text-muted">
                  {step.description}
                </p>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  );
}