import Link from "next/link";
import { Clock } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import type { HomeStats } from "@/components/sections/hero";

const emptyStats = {
  mockExams: 0,
  attempts: 0,
};

export function ModelTestsBand({
  stats = emptyStats,
}: {
  stats?: Pick<HomeStats, "mockExams" | "attempts">;
}) {
  return (
    <section className="bg-primary-dark px-6 py-20 text-cream lg:py-24">
      <div className="mx-auto grid max-w-6xl items-center gap-12 lg:grid-cols-2">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-accent">
            Model Tests
          </p>
          <h2 className="mt-4 font-heading text-3xl font-bold lg:text-4xl">
            Check your preparation with real exam simulations.
          </h2>
          <p className="mt-6 max-w-md leading-7 text-cream/75">
            Every model test runs on the actual exam clock and mirrors the real
            paper pattern.
          </p>
          <Link
            href="/model-tests"
            className="mt-8 inline-flex h-11 cursor-pointer items-center justify-center rounded-md border border-accent px-6 text-accent hover:bg-accent/10"
          >
            Explore Model Tests
          </Link>

          <div className="mt-8 flex items-center gap-8">
            <div>
              <p className="font-heading text-2xl font-bold text-cream">
                {stats.mockExams.toLocaleString()}
              </p>
              <p className="mt-1 text-xs text-cream/60">published mock exams</p>
            </div>
            <div className="h-10 w-px bg-cream/15" />
            <div>
              <p className="font-heading text-2xl font-bold text-cream">
                {stats.attempts.toLocaleString()}
              </p>
              <p className="mt-1 text-xs text-cream/60">attempts by students</p>
            </div>
          </div>
        </div>

        <Card className="ml-auto w-full max-w-md p-6 shadow-xl">
          <div className="flex items-center justify-between gap-4">
            <Badge className="border-accent text-xs text-accent">
              Preliminary
            </Badge>
            <span className="inline-flex items-center gap-2 text-xs text-muted">
              <Clock aria-hidden="true" size={15} />
              180 min
            </span>
          </div>
          <h3 className="mt-4 text-[17px] font-semibold text-primary">
            Criminal Procedure Code
          </h3>
          <p className="mt-1 text-[13px] text-muted">
            100 questions · Full syllabus
          </p>
          <div className="my-4 border-t border-border" />
          <div className="flex items-center justify-between gap-4">
            <Link
              href="/model-tests"
              className="inline-flex h-9 cursor-pointer items-center rounded-md bg-primary px-4 text-sm text-cream"
            >
              Start Test
            </Link>
            <Link
              href="/model-tests"
              className="inline-flex min-h-9 cursor-pointer items-center text-sm text-muted hover:text-foreground"
            >
              View details
            </Link>
          </div>
        </Card>
      </div>
    </section>
  );
}