import Image from "next/image";
import Link from "next/link";
import { ArrowRight } from "lucide-react";

import type { About } from "@/lib/types/about";

export type HomeStats = {
  students: number;
  publishedCourses: number;
  mockExams: number;
  attempts: number;
};

type HeroProps = {
  stats?: HomeStats;
  about?: Pick<About, "heroKicker" | "heroTitle" | "heroSubtitle"> | null;
};

const emptyStats: HomeStats = {
  students: 0,
  publishedCourses: 0,
  mockExams: 0,
  attempts: 0,
};

const trustItems = [
  "Mentor-led",
  "Model Tests",
  "Written Evaluation",
  "Lifetime Access",
];

export function Hero({ stats = emptyStats, about = null }: HeroProps) {
  const kicker = about?.heroKicker || "BANGLADESH JUDICIAL SERVICE";
  const title =
    about?.heroTitle ||
    "Prepare for the bench with structured, mentor-led training.";
  const subtitle =
    about?.heroSubtitle ||
    "Courses, model tests, and written evaluation built around the official BJS syllabus.";

  return (
    <section className="bg-cream px-6 py-20 md:py-24 lg:py-28">
      <div className="mx-auto grid max-w-6xl items-center gap-12 lg:grid-cols-2 lg:gap-16">
        <div className="order-2 lg:order-1">
          <p className="text-xs font-semibold uppercase tracking-[0.25em] text-accent">
            {kicker}
          </p>
          <h1 className="mt-4 max-w-2xl font-heading text-4xl font-bold leading-[1.05] tracking-tight text-primary sm:text-5xl lg:text-6xl">
            {title}
          </h1>
          <p className="mt-6 max-w-xl text-lg leading-relaxed text-muted">
            {subtitle}
          </p>
          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
            <Link
              href="/courses"
              className="inline-flex h-12 cursor-pointer items-center justify-center gap-2 rounded-md bg-primary px-6 font-medium text-cream hover:bg-primary/90"
            >
              Browse Courses
              <ArrowRight size={16} />
            </Link>
            <Link
              href="/register"
              className="inline-flex h-12 cursor-pointer items-center justify-center rounded-md border border-primary px-6 font-medium text-primary hover:bg-primary/5"
            >
              Get Started
            </Link>
          </div>
          <div className="mt-10 flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-muted">
            {trustItems.map((item, index) => (
              <span key={item} className="inline-flex items-center gap-6">
                {index > 0 ? (
                  <span
                    aria-hidden="true"
                    className="h-1.5 w-1.5 rounded-full bg-accent"
                  />
                ) : null}
                {item}
              </span>
            ))}
          </div>
          {stats.students > 0 || stats.publishedCourses > 0 ? (
            <p className="mt-5 text-xs text-muted">
              {stats.students > 0 ? (
                <span>{stats.students.toLocaleString()} learners</span>
              ) : null}
              {stats.students > 0 && stats.publishedCourses > 0 ? " · " : null}
              {stats.publishedCourses > 0 ? (
                <span>{stats.publishedCourses} published courses</span>
              ) : null}
            </p>
          ) : null}
        </div>

        <div className="relative order-1 mx-auto w-full max-w-md lg:order-2">
          <span
            aria-hidden="true"
            className="absolute -left-3 top-8 z-10 h-24 w-1 rounded-full bg-accent"
          />
          <div className="relative aspect-[4/5] w-full overflow-hidden rounded-lg shadow-md">
            {/* NOTE: The fixed-ratio frame stays in place when this image is unavailable. */}
            <Image
              src="/images/hero-mentor.jpg"
              alt="Mentor guiding BJS aspirants"
              fill
              priority
              sizes="(min-width: 1024px) 50vw, 100vw"
              className="object-cover"
            />
          </div>
        </div>
      </div>
    </section>
  );
}
