import type { Metadata } from "next";

import { FeaturedCourses, type PublicCourse } from "@/components/sections/featured-courses";
import { FinalCta } from "@/components/sections/final-cta";
import { Hero, type HomeStats } from "@/components/sections/hero";
import { HowToEnroll } from "@/components/sections/how-to-enroll";
import { MentorsPreview } from "@/components/sections/mentors-preview";
import { ModelTestsBand } from "@/components/sections/model-tests-band";
import { Testimonials } from "@/components/sections/testimonials";
import { WhyChooseUs } from "@/components/sections/why-choose-us";
import {
  aboutsCol,
  coursesCol,
  mentorsCol,
  preliminaryAttemptsCol,
  preliminaryExamsCol,
  successStoriesCol,
  usersCol,
} from "@/lib/collections";
import type { About } from "@/lib/types/about";
import type { Course } from "@/lib/types/course";
import type { Mentor, PublicMentor } from "@/lib/types/mentor";
import type {
  PublicSuccessStory,
  SuccessStory,
} from "@/lib/types/success-story";

export const metadata: Metadata = {
  title: "BJS Prep — Bangladesh Judicial Service Exam Preparation",
  description:
    "Structured, mentor-led preparation for the Bangladesh Judicial Service exam. Courses, model tests, and written evaluation.",
  openGraph: {
    title: "BJS Prep — Bangladesh Judicial Service Exam Preparation",
    description:
      "Structured, mentor-led preparation for the Bangladesh Judicial Service exam.",
    type: "website",
  },
};

export const revalidate = 60;

export default async function Home() {
  const [courses, mentors, stories, about, students, publishedCourses, mockExams, attempts] =
    await Promise.all([
      safeFetch<PublicCourse[]>(
        "featured courses",
        async () => {
          const records = await (await coursesCol())
            .find({ isPublished: true })
            .sort({ order: 1, createdAt: -1 })
            .limit(3)
            .toArray();

          return records.map(toPublicCourse);
        },
        [],
      ),
      safeFetch<PublicMentor[]>(
        "published mentors",
        async () => {
          const records = await (await mentorsCol())
            .find({ isPublished: true })
            .sort({ order: 1 })
            .limit(3)
            .toArray();

          return records.map(toPublicMentor);
        },
        [],
      ),
      safeFetch<PublicSuccessStory[]>(
        "featured success stories",
        async () => {
          const records = await (await successStoriesCol())
            .find({ status: "approved", isFeatured: true })
            .sort({ order: 1, createdAt: -1 })
            .limit(4)
            .toArray();

          return records.map(toPublicSuccessStory);
        },
        [],
      ),
      safeFetch<About | null>(
        "about content",
        async () => (await aboutsCol()).findOne({}),
        null,
      ),
      safeFetch("student count", async () => (await usersCol()).countDocuments(), 0),
      safeFetch(
        "published course count",
        async () =>
          (await coursesCol()).countDocuments({ isPublished: true }),
        0,
      ),
      safeFetch(
        "published mock exam count",
        async () =>
          (await preliminaryExamsCol()).countDocuments({ status: "published" }),
        0,
      ),
      safeFetch(
        "attempt count",
        async () => (await preliminaryAttemptsCol()).countDocuments(),
        0,
      ),
    ]);

  const stats: HomeStats = {
    students,
    publishedCourses,
    mockExams,
    attempts,
  };

  return (
    <>
      <Hero stats={stats} about={about} />
      <WhyChooseUs />
      <FeaturedCourses courses={courses} />
      <ModelTestsBand stats={stats} />
      <Testimonials stories={stories} />
      <HowToEnroll />
      <MentorsPreview mentors={mentors} />
      <FinalCta />
    </>
  );
}

async function safeFetch<T>(
  label: string,
  fetchData: () => Promise<T>,
  fallback: T,
): Promise<T> {
  try {
    return await fetchData();
  } catch (error) {
    console.error(`Homepage ${label} fetch failed`, error);
    return fallback;
  }
}

function toPublicCourse(course: Course): PublicCourse {
  return {
    _id: course._id,
    title: course.title,
    slug: course.slug,
    description: course.description,
    coverUrl: course.coverUrl,
    category: course.category,
    price: course.price,
    durationLabel: course.durationLabel,
  };
}

function toPublicMentor(mentor: Mentor): PublicMentor {
  const publicMentor = { ...mentor };
  Reflect.deleteProperty(publicMentor, "photoPublicId");
  return publicMentor;
}

function toPublicSuccessStory(story: SuccessStory): PublicSuccessStory {
  const publicStory = { ...story };
  Reflect.deleteProperty(publicStory, "authorEmail");
  Reflect.deleteProperty(publicStory, "authorPhotoPublicId");
  Reflect.deleteProperty(publicStory, "reviewedBy");
  return publicStory;
}
